// Skeleton: connect, batch render, offline queue
class DashboardClient {
  constructor() {
    this.state = { widgets: [] }
    this.queue = []
    this.renderScheduled = false
  }
  connect() {
    this.ws = new WebSocket('wss://example/live')
    this.ws.onmessage = e => {
      const d = JSON.parse(e.data)
      this.state.widgets = merge(this.state.widgets, d)
      this.scheduleRender()
    }
